		totalClosed,
		wins,
		losses,
		winRatePct: totalClosed > 0 ? Number((wins / totalClosed * 100).toFixed(2)) : 0,
		profitFactor: grossLoss > 0 ? Number((grossProfit / grossLoss).toFixed(2)) : grossProfit > 0 ? 99.99 : 0,
